// Filtrar alunos elegiveis para receber certificado
const enrollments = $input.all();
const eligible = [];

// IMPORTANTE: Substitua pelo ID real do seu template Google Slides
// O ID e o codigo na URL: https://docs.google.com/presentation/d/ESTE_ID_AQUI/edit
const TEMPLATE_ID = '15N7nRI7BkQeVm9YDiQRmYkjAulmtw9zVYqpgIigx8nE';

for (const enrollment of enrollments) {
  const data = enrollment.json;

  // Verificar se certificado ja foi enviado
  const certSent = String(data.certificate_sent || '').toLowerCase();
  if (certSent === 'true' || certSent === 'yes' || certSent === '1') continue;

  // Verificar elegibilidade: curso concluido OU presenca confirmada
  const isCompleted = String(data.status || '').toLowerCase() === 'completed';
  const isPresent = String(data.attendance || '').toLowerCase() === 'present';
  if (!isCompleted && !isPresent) continue;

  // Validar campos obrigatorios
  if (!data.name || !data.email) continue;

  // Formatar data do curso para o certificado (ex: "15 de Fevereiro de 2026")
  const courseDate = new Date(data.course_date);
  const meses = [
    'Janeiro', 'Fevereiro', 'Marco', 'Abril', 'Maio', 'Junho',
    'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
  ];
  const dataFormatada = courseDate.getDate() + ' de ' +
    meses[courseDate.getMonth()] + ' de ' + courseDate.getFullYear();

  // Gerar ID do certificado: CERT-YYYYMMDD-ENROLLID
  const certDate = courseDate.getFullYear() +
    String(courseDate.getMonth() + 1).padStart(2, '0') +
    String(courseDate.getDate()).padStart(2, '0');
  const certId = 'CERT-' + certDate + '-' + (data.enrollment_id || 'NA');

  eligible.push({
    json: {
      enrollment_id: data.enrollment_id,
      lead_id: data.lead_id,
      name: data.name,
      email: data.email,
      phone: data.phone || '',
      course_date: data.course_date,
      course_type: data.course_type,
      formatted_date: dataFormatada,
      certificate_id: certId,
      template_id: TEMPLATE_ID
    }
  });
}

return eligible.length > 0 ? eligible : [{ json: { skip: true, count: 0 } }];

